alter table public.fechou_members add column active boolean not null default true;
create or replace function public.fechou_role(p_workspace uuid) returns text language sql stable security definer set search_path='' as $$ select role from public.fechou_members where workspace_id=p_workspace and user_id=(select auth.uid()) and active and (select auth.jwt()->>'aal')='aal2' $$;
create or replace function public.fechou_add_member(p_workspace uuid,p_email text,p_name text,p_role text) returns void language plpgsql security definer set search_path='' as $$ declare v_user uuid; begin if public.fechou_role(p_workspace) is distinct from 'admin' then raise exception 'Somente administradores podem cadastrar acessos.'; end if; if p_role is null or p_role not in ('manager','seller') or p_name is null or char_length(trim(p_name)) not between 1 and 120 then raise exception 'Confira nome e cargo.'; end if; select id into v_user from auth.users where lower(email)=lower(trim(p_email)) and email_confirmed_at is not null limit 1; if v_user is null then raise exception 'A conta precisa existir e ter o e-mail confirmado.'; end if; insert into public.fechou_members(workspace_id,user_id,name,role) values(p_workspace,v_user,trim(p_name),p_role); insert into public.fechou_audit(workspace_id,actor_id,record_id,action) values(p_workspace,auth.uid(),v_user,'member_added'); end $$;
create function public.fechou_update_member(p_workspace uuid,p_member uuid,p_role text,p_active boolean) returns void language plpgsql security definer set search_path='' as $$ begin if public.fechou_role(p_workspace) is distinct from 'admin' or p_role is null or p_role not in ('manager','seller') or p_active is null then raise exception 'Alteração de acesso não autorizada.'; end if; update public.fechou_members set role=p_role,active=p_active where workspace_id=p_workspace and user_id=p_member and role<>'admin'; if not found then raise exception 'Acesso não encontrado.'; end if; insert into public.fechou_audit(workspace_id,actor_id,record_id,action) values(p_workspace,auth.uid(),p_member,'member_updated'); end $$;
revoke all on function public.fechou_update_member(uuid,uuid,text,boolean) from public, anon;
grant execute on function public.fechou_update_member(uuid,uuid,text,boolean) to authenticated;
create table public.fechou_ai_limits (user_id uuid not null, hour timestamptz not null, uses int not null, primary key(user_id,hour));
grant all on public.fechou_ai_limits to service_role;
alter table public.fechou_ai_limits enable row level security;
create function public.fechou_allow_ai(p_workspace uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare n integer; v_hour timestamptz:=date_trunc('hour', now()); begin if public.fechou_role(p_workspace) is null then return false; end if; insert into public.fechou_ai_limits as l values(auth.uid(),v_hour,1) on conflict(user_id,hour) do update set uses=l.uses+1 where l.uses<20 returning uses into n; delete from public.fechou_ai_limits where user_id=auth.uid() and hour<v_hour-interval '1 day'; return n is not null; end $$;
revoke all on function public.fechou_allow_ai(uuid) from public, anon;
grant execute on function public.fechou_allow_ai(uuid) to authenticated;